return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n % 100 == 1) ? 0 : ((n % 100 == 2) ? 1 : ((n % 100 == 3 || n % 100 == 4) ? 2 : 3));','language'=>'sl_SI','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:08+00:00','po-revision-date'=>'2026-11-05T19:51:08+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Dopolni manjkajoče prevode za vtičnike in teme, ki so že nameščeni na vašem spletišču.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Ta zaslon za nalaganje je bil zastarel: medtem je bilo pripravljeno drugo nalaganje. Nič ni bilo poslano. Trenutno nalaganje preglejte v razdelku Seznam prevodov.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Brezplačni paket storitve omogoča vsakemu spletišču omejeno število mest za vtičnike in teme; mesta v uporabi so prikazana v Nastavitvah, ko omogočite Babilim.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Z zahtevo za prevod bo ta vtičnik ali tema zasedel eno od mest brezplačnega paketa storitve za to spletišče (omejitev je %1$d za teme in %2$d za vtičnike), razen če ga že zaseda. Mesto ostane zasedeno, neuspel prevod pa ga ne sprosti.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Z zahtevo za prevod bo ta vtičnik ali tema zasedel eno od mest brezplačnega paketa storitve za to spletišče, razen če ga že zaseda. Mesto ostane zasedeno, neuspel prevod pa ga ne sprosti.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Če ta vtičnik ali tema še ne zaseda enega od mest brezplačnega paketa storitve za to spletišče, ga bo z zahtevo za prevod zasedel (omejitev je %1$d za teme in %2$d za vtičnike). Mesto ostane zasedeno, neuspel prevod pa ga ne sprosti. Želite nadaljevati?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Če ta vtičnik ali tema še ne zaseda enega od mest brezplačnega paketa storitve za to spletišče, ga bo z zahtevo za prevod zasedel. Mesto ostane zasedeno, neuspel prevod pa ga ne sprosti. Želite nadaljevati?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d spletišče v tem omrežju je nastavljeno tako, da ob izbrisu vtičnika izbriše svojo identiteto Babilim. Plačljive licence, vezane na to spletišče, potem ni mogoče samodejno obnoviti; obrniti se boste morali na podporo Babilim na %2$s. Če želite ohraniti identiteto, pritisnite Prekliči, odstranite kljukico pri "Ob odstranitvi izbriši vse podatke Babilim" v nastavitvah Babilim tega spletišča in znova deaktivirajte. Vseeno deaktiviram?' . "\0" . '%1$d spletišči v tem omrežju sta nastavljeni tako, da ob izbrisu vtičnika izbrišeta svojo identiteto Babilim. Plačljivih licenc, vezanih na ti spletišči, potem ni mogoče samodejno obnoviti; obrniti se boste morali na podporo Babilim na %2$s. Če želite ohraniti identiteti, pritisnite Prekliči, odstranite kljukico pri "Ob odstranitvi izbriši vse podatke Babilim" v nastavitvah Babilim vsakega spletišča in znova deaktivirajte. Vseeno deaktiviram?' . "\0" . '%1$d spletišča v tem omrežju so nastavljena tako, da ob izbrisu vtičnika izbrišejo svojo identiteto Babilim. Plačljivih licenc, vezanih na ta spletišča, potem ni mogoče samodejno obnoviti; obrniti se boste morali na podporo Babilim na %2$s. Če želite ohraniti identitete, pritisnite Prekliči, odstranite kljukico pri "Ob odstranitvi izbriši vse podatke Babilim" v nastavitvah Babilim vsakega spletišča in znova deaktivirajte. Vseeno deaktiviram?' . "\0" . '%1$d spletišč v tem omrežju je nastavljenih tako, da ob izbrisu vtičnika izbrišejo svojo identiteto Babilim. Plačljivih licenc, vezanih na ta spletišča, potem ni mogoče samodejno obnoviti; obrniti se boste morali na podporo Babilim na %2$s. Če želite ohraniti identitete, pritisnite Prekliči, odstranite kljukico pri "Ob odstranitvi izbriši vse podatke Babilim" v nastavitvah Babilim vsakega spletišča in znova deaktivirajte. Vseeno deaktiviram?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s ni ničesar za narediti.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Izberite jezik.','%d failed'=>'%d neuspešen' . "\0" . '%d neuspešna' . "\0" . '%d neuspešni' . "\0" . '%d neuspešnih','%d not yet tried'=>'%d še ni bil preizkušen' . "\0" . '%d še nista bila preizkušena' . "\0" . '%d še niso bili preizkušeni' . "\0" . '%d še ni bilo preizkušenih','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d poročilo čaka. »Always share« in »Don\'t share« veljata za vsa.' . "\0" . '%d poročili čakata. »Always share« in »Don\'t share« veljata za obe.' . "\0" . '%d poročila čakajo. »Always share« in »Don\'t share« veljata za vsa.' . "\0" . '%d poročil čaka. »Always share« in »Don\'t share« veljata za vsa.','%d skipped'=>'%d preskočen' . "\0" . '%d preskočena' . "\0" . '%d preskočeni' . "\0" . '%d preskočenih','%d succeeded'=>'%d uspešen' . "\0" . '%d uspešna' . "\0" . '%d uspešni' . "\0" . '%d uspešnih','%d to install'=>'%d za namestitev' . "\0" . '%d za namestitev' . "\0" . '%d za namestitev' . "\0" . '%d za namestitev','(a public key generated for this site)'=>'(javni ključ, ustvarjen za to spletišče)','(detected)'=>'(zaznano)','(generic codes and coordinates only)'=>'(samo splošne kode in koordinate)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čiščenje je bilo ustavljeno ob %1$s: %2$s. Nič ni bilo izbrisano.','A file in the component could not be read, so it was not packaged.'=>'Datoteke v komponenti ni bilo mogoče prebrati, zato ni bila dodana v paket.','A host that serves only one PHP request at a time cannot complete this step.'=>'Gostitelj, ki hkrati obdela samo eno zahtevo PHP, tega koraka ne more dokončati.','A part of the upload kept failing, so the upload was cancelled.'=>'Del nalaganja je ves čas odpovedoval, zato je bilo nalaganje preklicano.','A translation cannot be requested for that locale on this site right now.'=>'Za ta jezik na tem spletišču trenutno ni mogoče zahtevati prevoda.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Zapis v indeks prevodov je ob %1$s (%2$s) trčil z drugo zahtevo in ni bil uveljavljen; ohranjena je bila najnovejša različica.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Zapisa v indeks prevodov ob %1$s (%2$s) ni bilo mogoče dokončati in ni bil uveljavljen (%3$s).','Account'=>'Račun','Add another language'=>'Dodaj še en jezik','Advanced'=>'Napredno','All'=>'Vse','All free-plan slots for this site are used'=>'Vsa mesta brezplačnega paketa za to spletišče so zasedena','All languages'=>'Vsi jeziki','Already in WordPress core'=>'Že v jedru WordPress','Already installed.'=>'Že nameščeno.','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'Poteka druga namestitev; poskusite znova čez trenutek.','Automatic installs'=>'Samodejne namestitve','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Samodejne namestitve so zdaj izklopljene; če jih želite, jih znova vklopite v nastavitvah.','Available'=>'Na voljo','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Razpoložljive prevode lahko namestite z enim klikom, manjkajoče pa lahko zahtevate. Ko so samodejne namestitve vklopljene, se prevodi, ki jih storitev navaja kot razpoložljive za jezike, ki jih upravljate, namestijo med sinhronizacijo dvakrat na dan.','Available · %s'=>'Na voljo · %s','Babilim Settings'=>'Nastavitve Babilim','Babilim adds translations for every language checked here.'=>'Babilim doda prevode za vse tukaj izbrane jezike.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ni mogel potrditi začasne mape zunaj spletnega mesta, zato komponenta ni bila zapakirana in ni bilo naloženo nič. Določite BABILIM_TEMP_DIR v wp-config.php kot zapisljivo mapo zunaj korenskega imenika spletnega mesta (na primer mapo poleg javnega imenika vašega spletišča, ne v njem) ali jo zahtevajte pri ponudniku gostovanja.','Babilim could not finish checking this site.'=>'Babilim ni mogel dokončati preverjanja tega spletišča.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ni 